import sys
sys.setrecursionlimit(10**6)

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    if n == 1:
        print("1")
        return

    adj = [[] for _ in range(n + 1)]
    idx = 1
    for _ in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    sz = [1] * (n + 1)
    for u in reversed(order):
        p = parent[u]
        if p != 0:
            sz[p] += sz[u]

    def get_max_comp(u):
        max_c = n - sz[u]
        for v in adj[u]:
            if v != parent[u]:
                if sz[v] > max_c:
                    max_c = sz[v]
        return max_c

    def can_make_centroid(u):
        if n == 1:
            return True

        max_c = get_max_comp(u)
        if max_c <= n // 2:
            return True

        largest_sub = 0
        largest_sub_node = -1
        for v in adj[u]:
            if v != parent[u] and sz[v] > largest_sub:
                largest_sub = sz[v]
                largest_sub_node = v

        outside = n - sz[u]

        if largest_sub > n // 2:
            if largest_sub_node == -1:
                return False

            heavy_sz = sz[largest_sub_node]

            if outside >= n // 2:
                return False

            if heavy_sz > n - 1:
                return False

            if heavy_sz == n - 1:
                if outside == 0:
                    return False
                else:
                    return True

            if heavy_sz <= n // 2:
                return True

            if heavy_sz > n // 2:
                if outside == 0:
                    return False

                if heavy_sz <= n - 1 - (n // 2):
                    return True

                if heavy_sz > n - 1 - (n // 2):
                    return False

                return True

        return False

    res = []
    for i in range(1, n + 1):
        if can_make_centroid(i):
            res.append("1")
        else:
            res.append("0")

    print(" ".join(res))

if __name__ == "__main__":
    main()
